class Solution:
    def countSubranges(self, nums1: List[int], nums2: List[int]) -> int:
        MOD = 10 ** 9 + 7
        dp = {}
        ans = 0
        for i in range(len(nums1)):
            a, b = nums1[i], nums2[i]
            ndp = {}
            ndp[a] = (ndp.get(a, 0) + 1) % MOD
            neg = -b
            ndp[neg] = (ndp.get(neg, 0) + 1) % MOD
            for bal, ways in dp.items():
                for nb in (bal + a, bal - b):
                    ndp[nb] = (ndp.get(nb, 0) + ways) % MOD
            ans = (ans + ndp.get(0, 0)) % MOD
            dp = ndp
        return ans

