class Solution {
public:
    int countSubranges(vector<int>& nums1, vector<int>& nums2) {
        const long long MOD = 1e9 + 7;
        unordered_map<int, long long> dp;
        long long ans = 0;
        for (int i = 0; i < (int)nums1.size(); i++) {
            unordered_map<int, long long> ndp;
            int a = nums1[i], b = nums2[i];
            ndp[a]++;
            ndp[-b]++;
            for (auto& [bal, ways] : dp) {
                ndp[bal + a] = (ndp[bal + a] + ways) % MOD;
                ndp[bal - b] = (ndp[bal - b] + ways) % MOD;
            }
            auto it = ndp.find(0);
            if (it != ndp.end()) ans = (ans + it->second) % MOD;
            dp = move(ndp);
        }
        return (int)ans;
    }
};

