class Solution {
    public int countSubranges(int[] nums1, int[] nums2) {
        final long MOD = 1_000_000_007L;
        Map<Integer, Long> dp = new HashMap<>();
        long ans = 0;
        for (int i = 0; i < nums1.length; i++) {
            Map<Integer, Long> ndp = new HashMap<>();
            int a = nums1[i], b = nums2[i];
            ndp.merge(a, 1L, Long::sum);
            ndp.merge(-b, 1L, Long::sum);
            for (Map.Entry<Integer, Long> e : dp.entrySet()) {
                ndp.put(e.getKey() + a, (ndp.getOrDefault(e.getKey() + a, 0L) + e.getValue()) % MOD);
                ndp.put(e.getKey() - b, (ndp.getOrDefault(e.getKey() - b, 0L) + e.getValue()) % MOD);
            }
            ans = (ans + ndp.getOrDefault(0, 0L)) % MOD;
            dp = ndp;
        }
        return (int) ans;
    }
}

