                    if j - b >= 0:
                        ndp[j - b] = (ndp[j - b] + v) % MOD
            ndp[off + a] = (ndp[off + a] + 1) % MOD
            ndp[off - b] = (ndp[off - b] + 1) % MOD
            ans = (ans + ndp[off]) % MOD
            dp = ndp
