class Solution {
public:
    int countSubranges(vector<int>& nums1, vector<int>& nums2) {
        const int MOD = 1e9 + 7, OFF = 10000, S = 20001;
        vector<long long> dp(S, 0), ndp(S);
        long long ans = 0;
        for (int i = 0; i < (int)nums1.size(); i++) {
            fill(ndp.begin(), ndp.end(), 0LL);
            int a = nums1[i], b = nums2[i];
            for (int j = 0; j < S; j++) {
                if (dp[j] == 0) continue;
                int ja = j + a, jb = j - b;
                if (ja >= 0 && ja < S) ndp[ja] = (ndp[ja] + dp[j]) % MOD;
                if (jb >= 0 && jb < S) ndp[jb] = (ndp[jb] + dp[j]) % MOD;
            }
            ndp[OFF + a] = (ndp[OFF + a] + 1) % MOD;
            ndp[OFF - b] = (ndp[OFF - b] + 1) % MOD;
            ans = (ans + ndp[OFF]) % MOD;
            swap(dp, ndp);
        }
        return (int)ans;
    }
};

